g=[[0,5,0,0,0,0,0,5,0,0,5,0],[0,5,0,0,0,5,5,5,0,5,5,0],[5,5,5,0,0,5,0,5,5,5,0,0],[0,0,5,5,5,5,0,5,0,5,5,0],[0,0,0,5,0,0,0,5,0,0,5,0]]
from collections import deque
R,C=5,12; seen=set(); cs=[]
for r in range(R):
 for c in range(C):
  if g[r][c]==0 and (r,c) not in seen:
   q=deque([(r,c)]);seen.add((r,c)); comp=[]
   while q:
    x,y=q.popleft();comp.append((x,y))
    for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
     if 0<=a<R and 0<=b<C and g[a][b]==0 and (a,b) not in seen:seen.add((a,b));q.append((a,b))
   cs.append(comp)
print([(len(x),min(x),max(x)) for x in sorted(cs,key=len,reverse=True)])
